192	    shutdown: CancellationToken,
193	) -> Result<()> {
194	    let model_id = model_id.into();
195	    let adapter_names = Arc::new(RwLock::new(HashSet::new()));
196	    // The Option is the capability: only engines that minted a LoRA channel
197	    // can serve these routes.
198	    let control = engine
199	        .lora
200	        .clone()
201	        .ok_or_else(|| anyhow::anyhow!("engine does not expose LoRA adapter control"))?;
202	    load_startup_lora_modules(&control, &adapter_names, &lora_modules).await?;
203	    let base_model_name = served_model_name
204	        .first()
205	        .cloned()
206	        .unwrap_or_else(|| model_id.clone());
207	    serve_model_on_host_with_router_extension(
208	        std::future::ready(Ok(LaunchedEngine::Stepped(engine))),
209	        model_id,
210	        served_model_name.clone(),
211	        tool_call_parser,
212	        "0.0.0.0".to_string(),
213	        port,
214	        max_model_len,
215	        1,
216	        shutdown,
217	        move |router| {
218	            let lora_router = lora_routes(control, Arc::clone(&adapter_names));
219	            let openai_router = lora_openai_routes(
220	                router.clone(),
221	                base_model_name,
222	                served_model_name,
223	                Arc::clone(&adapter_names),
224	            );
225	            openai_router.merge(lora_router).fallback_service(router)
226	        },
227	    )
228	    .await
229	}
230	
231	async fn serve_model_on_host(
232	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
233	    model_id: String,
234	    served_model_name: Vec<String>,
235	    tool_call_parser: ParserSelection,
236	    host: String,
237	    port: u16,
238	    max_model_len: u32,
239	    engine_count: usize,
240	    shutdown: CancellationToken,
241	) -> Result<()> {
242	    serve_model_on_host_with_router_extension(
243	        engine,
244	        model_id,
245	        served_model_name,
246	        tool_call_parser,
247	        host,
248	        port,
249	        max_model_len,
250	        engine_count,
251	        shutdown,
252	        |router| router,
253	    )
254	    .await
255	}
256	
257	async fn serve_model_on_host_with_router_extension<F>(
258	    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
259	    model_id: String,
260	    served_model_name: Vec<String>,
261	    tool_call_parser: ParserSelection,
262	    host: String,
263	    port: u16,
264	    max_model_len: u32,
265	    engine_count: usize,
266	    shutdown: CancellationToken,
267	    extend_router: F,
268	) -> Result<()>
269	where
270	    F: FnOnce(Router) -> Router,
271	{
272	    ensure!(engine_count > 0, "frontend engine_count must be positive");
273	    let data_parallel_size = u32::try_from(engine_count)
274	        .map_err(|_| anyhow::anyhow!("frontend engine_count {engine_count} exceeds u32"))?;
275	    let namespace = local_ipc_namespace()?;
276	    let input_address = ipc_endpoint(&namespace, "input.sock");
277	    let output_address = ipc_endpoint(&namespace, "output.sock");
278	    // vllm-server adopts already-bound listeners (the supervisor's role in
279	    // upstream's Python deployment); binding them here means the bridge can
280	    // connect at any time, the server owns and closes the descriptors.
281	    let input_listener_fd = UnixListener::bind(namespace.join("input.sock"))?.into_raw_fd();
282	    let output_listener_fd = UnixListener::bind(namespace.join("output.sock"))?.into_raw_fd();
283	
284	    // The HTTP server runs concurrently with the engine load: vllm-server
285	    // spends ~1s loading the tokenizer and chat templates before it waits for
286	    // an engine to register, so neither waits on the other. This task attaches
287	    // the bridge once the engine resolves and runs it to completion; on engine
288	    // failure it cancels the server so the error surfaces instead of hanging
289	    // in the registration wait.
290	    let server_shutdown = shutdown.child_token();
291	    let bridge_shutdown = shutdown.child_token();
292	    let engine_task = tokio::spawn({
293	        let server_shutdown = server_shutdown.clone();
294	        let bridge_shutdown = bridge_shutdown.clone();
295	        let input_address = input_address.clone();
296	        let output_address = output_address.clone();
297	        async move {
298	            let launched = match engine.await {
299	                Ok(launched) => launched,
300	                Err(error) => {
301	                    server_shutdown.cancel();
302	                    return Err(error);
303	                }
304	            };
305	            let mut bridges = tokio::task::JoinSet::new();
306	            // Stepped engines own their scheduler threads; reaped below after
307	            // the bridges (and with them the scheduler handles) are gone.
308	            let mut scheduler_joins: Vec<std::thread::JoinHandle<()>> = Vec::new();
309	            match launched {
310	                LaunchedEngine::Handle(handle) => {
311	                    let actual_partitions = handle.scheduler_partition_count();
312	                    if actual_partitions != engine_count {
313	                        server_shutdown.cancel();
314	                        anyhow::bail!(
315	                            "frontend declared {engine_count} engines but the resolved handle \
316	                             exposes {actual_partitions} scheduler partitions"
317	                        );
318	                    }
319	                    let servable_limit = handle.servable_len().map(|cap| max_model_len.min(cap));
320	                    let max_model_len = servable_limit.unwrap_or(max_model_len);
321	                    for engine_index in 0..engine_count {
322	                        let bridge = LocalEngineBridge {
323	                            input_address: input_address.clone(),
324	                            output_address: output_address.clone(),
325	                            handle: handle.clone(),
326	                            max_model_len,
327	                            engine_index: engine_index as u32,
328	                            data_parallel_size,
329	                            metrics_watch: handle.metrics_watch_for(engine_index),
330	                        };
331	                        let shutdown = bridge_shutdown.clone();
332	                        bridges.spawn(async move { (engine_index, bridge.run(shutdown).await) });
333	                    }
334	                    drop(handle);
335	                }
336	                LaunchedEngine::Stepped(engine) => {
337	                    let actual_schedulers = engine.schedulers.len();
338	                    if actual_schedulers != engine_count {
339	                        server_shutdown.cancel();
340	                        anyhow::bail!(
341	                            "frontend declared {engine_count} engines but the launched engine \
342	                             exposes {actual_schedulers} schedulers"
343	                        );
344	                    }
345	                    let info = engine.info;
346	                    let servable_limit = info.servable_len.map(|cap| max_model_len.min(cap));
347	                    let max_model_len = servable_limit.unwrap_or(max_model_len);
348	                    for (engine_index, scheduler) in engine.schedulers.into_iter().enumerate() {
349	                        scheduler_joins.push(scheduler.join);
350	                        let bridge = bridge::SteppedEngineBridge {
351	                            input_address: input_address.clone(),
352	                            output_address: output_address.clone(),
353	                            scheduler: scheduler.handle,
354	                            kv_capacity: info.kv_capacity,
355	                            max_model_len,
356	                            engine_index: engine_index as u32,
357	                            data_parallel_size,
358	                        };
359	                        let shutdown = bridge_shutdown.clone();
360	                        bridges.spawn(async move { (engine_index, bridge.run(shutdown).await) });
361	                    }
362	                }
363	            }
364	
365	            let mut bridge_error = None;
366	            while let Some(joined) = bridges.join_next().await {
367	                match joined {
368	                    Ok((_, Ok(()))) if bridge_shutdown.is_cancelled() => {}
369	                    Ok((engine_index, Ok(()))) => {
370	                        bridge_error = Some(anyhow::anyhow!(
371	                            "local vLLM engine {engine_index} bridge exited unexpectedly"
372	                        ));
373	                        break;
374	                    }
375	                    Ok((engine_index, Err(error))) => {
376	                        bridge_error = Some(
377	                            error
378	                                .context(format!("local vLLM engine {engine_index} bridge failed")),
379	                        );
380	                        break;
381	                    }
382	                    Err(error) => {
383	                        bridge_error = Some(anyhow::anyhow!(
384	                            "local vLLM engine bridge task panicked: {error}"
385	                        ));
386	                        break;
387	                    }
388	                }
389	            }
390	            if bridge_error.is_some() {
391	                server_shutdown.cancel();
392	                bridge_shutdown.cancel();
393	                // Let the other bridges abort their requests and flush their output.
394	                while bridges.join_next().await.is_some() {}
395	            }
396	            // The bridges are gone, and with them the partition handles:
397	            // submission channels are disconnected, so the drivers drain and
398	            // exit. Reap their threads to surface scheduler panics.
399	            if !scheduler_joins.is_empty() {
400	                let _ = tokio::task::spawn_blocking(move || {
401	                    for join in scheduler_joins {
402	                        if join.join().is_err() {
403	                            warn!("scheduler thread panicked during shutdown");
404	                        }
405	                    }
406	                })
407	                .await;
408	            }
409	            match bridge_error {
410	                Some(error) => Err(error),
411	                None => Ok(()),
412	            }
413	        }
414	    });
415	
416	    // The two request-shaping layers read the served checkpoint's template and
417	    // tokenizer, loaded once here; the server loads its own afterwards and
418	    // reports its own error if the model is genuinely broken.
419	    let backends = match load_model_backends(
420	        &model_id,
421	        LoadModelBackendsOptions {
422	            language_model_only: true,
423	            ..Default::default()
424	        },
425	    )
426	    .await
427	    {
428	        Ok(backends) => Some(backends),
429	        Err(error) => {
430	            warn!("chat request shaping disabled: backends for {model_id} did not load: {error}");
431	            None
432	        }
433	    };
434	    let effort_aliases = reasoning_effort::probe_effort_aliases(&model_id, backends.as_ref());
435	    let boundary = backends.map(|b| Arc::new(history::Boundary::new(&b)));
436	
437	    let config = Config {
438	        transport_mode: TransportMode::Bootstrapped {
439	            input_listener_fd,
440	            output_listener_fd,
441	            engine_start_index: 0,
442	            engine_count,
443	            data_parallel_size: engine_count,
444	            // The in-process bridge registers once the engine future resolves,
445	            // so this bounds the whole engine load (multi-GPU MoE models take
446	            // minutes, cold starts longer). Load *failure* already cancels the
447	            // server via the engine task; this only catches a truly hung load.
448	            ready_timeout: Duration::from_mins(30),
449	        },
450	        coordinator_mode: CoordinatorMode::None,
451	        model: model_id,
452	        revision: None,
453	        hf_overrides: HfOverrides::default(),
454	        generation_config: GenerationConfigMode::Auto,
455	        served_model_name,
456	        listener_mode: HttpListenerMode::BindTcp { host, port },
457	        tool_call_parser,
458	        reasoning_parser: ParserSelection::default(),
459	        tool_strict_level: None,
460	        renderer: RendererSelection::default(),
461	        chat_template: None,
462	        default_chat_template_kwargs: None,
463	        limit_mm_per_prompt: HashMap::new(),
464	        // Startup adapters go through the engine-side LoRA channel
465	        // (`load_startup_lora_modules`), never the upstream static loader.
466	        lora_modules: Vec::new(),
467	        chat_template_content_format: ChatTemplateContentFormatOption::default(),
468	        max_logprobs: None,
469	        language_model_only: true,
470	        cors: CorsConfig::default(),
471	        api_keys: Vec::new(),
472	        api_server_options: ApiServerOptions {
473	            enable_log_requests: true,
474	            enable_prompt_tokens_details: true,
475	            enable_request_id_headers: false,
476	            enable_scale_out: false,
477	            enable_per_request_metrics: false,
478	            sse_keep_alive_interval: None,
479	        },
480	        // Upstream ties the scheduler-stats and request-event metric recorders
481	        // to this flag, and the bridge's stats are what `/metrics` exports; the
482	        // periodic stats log line comes with it.
483	        disable_log_stats: false,
484	        grpc_listener_mode: None,
485	        manages_engine: false,
486	        shutdown_timeout: Duration::from_secs(10),
487	        stream_interval: NonZeroU32::MIN,
488	        keep_alive_timeout: DEFAULT_KEEP_ALIVE_TIMEOUT,
489	        profiler: None,
490	        tls: None,
491	    };
492	
493	    let result = vllm_server::serve_with_router_extension(config, server_shutdown, move |router| {
494	        // Effort normalization is outermost so the boundary measures the
495	        // template under the value the route will render with.
496	        reasoning_effort::normalize_chat_requests(
497	            history::mark_history(extend_router(router), boundary),
498	            effort_aliases,
499	        )
500	    })
501	    .await;
502	    // Stop the bridge (no-op if the caller's shutdown already cancelled it),
503	    // then collect the engine task. If the server failed while the engine is
504	    // still loading, the uncancellable blocking load must finish first.
505	    bridge_shutdown.cancel();
506	    if result.is_err() && !engine_task.is_finished() {
507	        warn!("HTTP server failed; waiting for the in-flight engine load to finish before exit");
508	    }
509	    let result = match engine_task.await {
510	        Ok(Ok(())) => result,
511	        // Engine failed: the server saw a cancel and returned Ok — the engine
512	        // error is the one worth reporting.
513	        Ok(Err(engine_error)) => result.and(Err(engine_error)),
514	        Err(join_error) => result.and(Err(anyhow::anyhow!(
515	            "engine startup task panicked: {join_error}"
516	        ))),
517	    };
518	    let _ = std::fs::remove_dir_all(namespace);
519	    result
520	}
521	
522	pub fn load_max_model_len(model_path: &Path) -> Option<u32> {
523	    let content = std::fs::read_to_string(model_path.join("config.json")).ok()?;
524	    serde_json::from_str::<ModelLenConfig>(&content)
525	        .ok()?
526	        .max_model_len()
527	}
528	
529	fn resolve_max_model_len(model_path: &Path, max_model_len: Option<u32>) -> u32 {
530	    max_model_len.unwrap_or_else(|| {
531	        load_max_model_len(model_path).unwrap_or_else(|| {
532	            const FALLBACK_MAX_MODEL_LEN: u32 = 4096;
533	            warn!(
534	                "max_position_embeddings not found in {}/config.json; capping max_model_len at {FALLBACK_MAX_MODEL_LEN}. \
535	                 Requests are limited to this length — set max_position_embeddings in the model config if it supports more.",
536	                model_path.display()
537	            );
538	            FALLBACK_MAX_MODEL_LEN
539	        })
540	    })
541	}
542	
543	/// Cancel `token` on the first CTRL+C. Installing the handler replaces the
544	/// default SIGINT kill behavior — only call this once whatever the token
545	/// guards can actually wind down (e.g. after an uncancellable blocking engine
546	/// load has finished), otherwise CTRL+C turns into a no-op wait.
547	pub fn cancel_token_on_ctrl_c(token: &CancellationToken) {
548	    let shutdown = token.clone();
549	    tokio::spawn(async move {
550	        if let Err(error) = tokio::signal::ctrl_c().await {
551	            warn!("failed to install CTRL+C handler: {error}");
552	        }
553	        shutdown.cancel();
554	    });
555	}
556	
557	pub fn shutdown_token_from_ctrl_c() -> CancellationToken {
558	    let token = CancellationToken::new();
559	    cancel_token_on_ctrl_c(&token);
560	    token
561	}
